  [handlersMapSymbol]?: Map<string, CacheHandler>
  [handlersSetSymbol]?: Set<CacheHandler>
  [customCacheHandlersRegistrationSymbol]?: Promise<void>
  [builtInHandlersSymbol]?: Set<CacheHandler>
